class Solution:
    def minimumWeight(self, edges: List[List[int]], queries: List[List[int]]) -> List[int]:
        from collections import deque
        n = len(edges) + 1
        LOG = max(1, n.bit_length())
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w)); adj[v].append((u, w))
        par = [[0] * n for _ in range(LOG)]
        dep = [0] * n
        wd = [0] * n
        seen = [False] * n
        dq = deque([0]); seen[0] = True
        while dq:
            u = dq.popleft()
            for v, w in adj[u]:
                if not seen[v]:
                    seen[v] = True
                    par[0][v] = u; dep[v] = dep[u] + 1; wd[v] = wd[u] + w
                    dq.append(v)
        for j in range(1, LOG):
            for v in range(n):
                par[j][v] = par[j-1][par[j-1][v]]
        def lca(a, b):
            if dep[a] < dep[b]: a, b = b, a
            d = dep[a] - dep[b]
            for j in range(LOG):
                if d >> j & 1: a = par[j][a]
            if a == b: return a
            for j in range(LOG - 1, -1, -1):
                if par[j][a] != par[j][b]:
                    a = par[j][a]; b = par[j][b]
            return par[0][a]
        def dist(a, b):
            return wd[a] + wd[b] - 2 * wd[lca(a, b)]
        return [(dist(a, b) + dist(a, c) + dist(b, c)) // 2 for a, b, c in queries]

