class Solution {
public:
    vector<int> minimumWeight(vector<vector<int>>& edges, vector<vector<int>>& queries) {
        int n = edges.size() + 1, LOG = 1;
        while ((1 << LOG) < n) LOG++;
        vector<vector<pair<int,int>>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back({e[1], e[2]}); adj[e[1]].push_back({e[0], e[2]}); }
        vector<vector<int>> up(LOG, vector<int>(n, 0));
        vector<long long> wd(n, 0); vector<int> dep(n, 0);
        vector<bool> vis(n, false); vis[0] = true;
        vector<int> stk = {0};
        while (!stk.empty()) {
            int u = stk.back(); stk.pop_back();
            for (auto [v, w] : adj[u]) if (!vis[v]) { vis[v] = true; up[0][v] = u; dep[v] = dep[u] + 1; wd[v] = wd[u] + w; stk.push_back(v); }
        }
        for (int j = 1; j < LOG; j++) for (int v = 0; v < n; v++) up[j][v] = up[j-1][up[j-1][v]];
        auto lca = [&](int a, int b) {
            if (dep[a] < dep[b]) swap(a, b);
            int d = dep[a] - dep[b];
            for (int j = 0; j < LOG; j++) if (d >> j & 1) a = up[j][a];
            if (a == b) return a;
            for (int j = LOG - 1; j >= 0; j--) if (up[j][a] != up[j][b]) { a = up[j][a]; b = up[j][b]; }
            return up[0][a];
        };
        auto dist = [&](int a, int b) { return wd[a] + wd[b] - 2 * wd[lca(a, b)]; };
        vector<int> ans;
        for (auto& q : queries) ans.push_back((dist(q[0], q[1]) + dist(q[0], q[2]) + dist(q[1], q[2])) / 2);
        return ans;
    }
};

