class Solution {
    public int[] minimumWeight(int[][] edges, int[][] queries) {
        int n = edges.length + 1, LOG = 1;
        while ((1 << LOG) < n) LOG++;
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(new int[]{e[1], e[2]}); adj.get(e[1]).add(new int[]{e[0], e[2]}); }
        int[][] up = new int[LOG][n];
        long[] wd = new long[n]; int[] dep = new int[n];
        boolean[] vis = new boolean[n]; vis[0] = true;
        Deque<Integer> stk = new ArrayDeque<>(); stk.push(0);
        while (!stk.isEmpty()) {
            int u = stk.pop();
            for (int[] ed : adj.get(u)) { int v = ed[0]; if (!vis[v]) { vis[v] = true; up[0][v] = u; dep[v] = dep[u] + 1; wd[v] = wd[u] + ed[1]; stk.push(v); } }
        }
        for (int j = 1; j < LOG; j++) for (int v = 0; v < n; v++) up[j][v] = up[j-1][up[j-1][v]];
        java.util.function.BinaryOperator<Integer> lcaF = (x, y) -> {
            int a = x, b = y;
            if (dep[a] < dep[b]) { int t = a; a = b; b = t; }
            int d = dep[a] - dep[b];
            for (int j = 0; j < LOG; j++) if (((d >> j) & 1) == 1) a = up[j][a];
            if (a == b) return a;
            for (int j = LOG - 1; j >= 0; j--) if (up[j][a] != up[j][b]) { a = up[j][a]; b = up[j][b]; }
            return up[0][a];
        };
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int a = queries[i][0], b = queries[i][1], c = queries[i][2];
            long dab = wd[a] + wd[b] - 2 * wd[lcaF.apply(a, b)];
            long dac = wd[a] + wd[c] - 2 * wd[lcaF.apply(a, c)];
            long dbc = wd[b] + wd[c] - 2 * wd[lcaF.apply(b, c)];
            ans[i] = (int) ((dab + dac + dbc) / 2);
        }
        return ans;
    }
}

