var minimumWeight = function(edges, queries) {
    const n = edges.length + 1;
    let LOG = 1; while ((1 << LOG) < n) LOG++;
    const adj = Array.from({length: n}, () => []);
    for (const [u, v, w] of edges) { adj[u].push([v, w]); adj[v].push([u, w]); }
    const up = Array.from({length: LOG}, () => new Array(n).fill(0));
    const wd = new Array(n).fill(0), dep = new Array(n).fill(0), vis = new Array(n).fill(false);
    vis[0] = true; const stk = [0];
    while (stk.length) {
        const u = stk.pop();
        for (const [v, w] of adj[u]) if (!vis[v]) { vis[v] = true; up[0][v] = u; dep[v] = dep[u] + 1; wd[v] = wd[u] + w; stk.push(v); }
    }
    for (let j = 1; j < LOG; j++) for (let v = 0; v < n; v++) up[j][v] = up[j-1][up[j-1][v]];
    const lca = (x, y) => {
        let a = x, b = y;
        if (dep[a] < dep[b]) [a, b] = [b, a];
        let d = dep[a] - dep[b];
        for (let j = 0; j < LOG; j++) if ((d >> j) & 1) a = up[j][a];
        if (a === b) return a;
        for (let j = LOG - 1; j >= 0; j--) if (up[j][a] !== up[j][b]) { a = up[j][a]; b = up[j][b]; }
        return up[0][a];
    };
    const dist = (a, b) => wd[a] + wd[b] - 2 * wd[lca(a, b)];
    return queries.map(([a, b, c]) => (dist(a, b) + dist(a, c) + dist(b, c)) / 2);
};
